import { readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
const dir=import.meta.dirname
const ui=JSON.parse(readFileSync(join(dir,'evidencia-ui/resultados-edge.json')))
const ff=JSON.parse(readFileSync(join(dir,'evidencia-ui/resultados-firefox.json')))
const tec=JSON.parse(readFileSync(join(dir,'evidencia_tecnica.json')))
const pub=JSON.parse(readFileSync(join(dir,'evidencia-publica.json')))
const findings=[
{id:'MC01',p:'P1',area:'Reglas e integridad',estado:'Reproducido',title:'La pantalla y caja aplican topes diferentes al reingresar',problem:'Después de usar la bolsa, vencer y volver a contratar en el mismo mes, /yo marca la bolsa como retirada por el historial de la persona. La solicitud y entrega consultan la nueva membresía y permiten otra bolsa. La prueba produjo dos entregas en la misma ventana mensual mientras la interfaz negaba disponibilidad.',impact:'Puede ocultarse un derecho pagado o concederse una entrega contraria a la regla elegida. La segunda cuota sí fue pagada: no corresponde llamar fraude a este caso.',fix:'Definir la unidad del derecho —persona, membresía o período pagado— y compartir una única evaluación entre consulta, solicitud, entrega e índice de unicidad.',accept:'Uso → vencimiento → reingreso en el mismo día/mes: cliente, API y caja devuelven la misma disponibilidad, razón y próxima fecha. Probar bolsa y café.',owner:'Producto + backend + operación',evidence:'T03 en evidencia_tecnica.json; src/worker/index.ts:478; operacion.ts:97; db/003_correcciones.sql:60; Club.tsx:316.'},
{id:'MC02',p:'P1',area:'Propuesta comercial',estado:'Código confirmado',title:'«Un café por visita» se limita a uno por día',problem:'La oferta y el beneficio dicen por visita. El servidor usa bebida_dia y una ventana por fecha de Managua. Dos visitas legítimas en un día no generan dos derechos.',impact:'La expectativa de quien paga puede ser distinta del servicio que caja puede entregar.',fix:'Dirección debe escoger la regla. Si se conserva la implementación actual, comunicar un café filtrado por día, con tamaño, extras, horarios y condiciones. Si se elige por visita, definir y registrar una visita elegible.',accept:'Oferta, condiciones, código y guion de caja responden igual a una segunda visita ese día. La regla se conoce antes del cobro.',owner:'Dirección + producto',evidence:'Club.tsx:248,335; src/worker/operacion.ts:99,117; findings_comercial.md C01.'},
{id:'MC03',p:'P1',area:'Propuesta comercial',estado:'Reglas confirmadas; efecto de calendario deducido',title:'Treinta días de pago y una bolsa por mes usan calendarios distintos',problem:'El cobro extiende treinta días, el precio dice /mes y la bolsa se reinicia el día 1. Un período puede atravesar dos ventanas; del 31 de enero al 2 de marzo de 2027 abarca tres meses calendario. No hay un contrato visible que explique esa diferencia.',impact:'Cambia el costo de servir la membresía y lo que significa una bolsa por cuota. Treinta días tampoco coincide siempre con una fecha fija mensual.',fix:'Elegir explícitamente ciclo de treinta días o mes de aniversario, y bolsa por período o calendario. Modelar el período y sus derechos; mostrar fecha de cobro y de siguiente bolsa. Respetar los derechos ya vendidos al migrar.',accept:'Casos de 28, 29, 30 y 31 días con conteo acordado de cuotas y bolsas; igual explicación en venta, contrato, API y caja.',owner:'Dirección + finanzas + backend',evidence:'Club.tsx:233,492,519; index.ts:820; db/018_clientes_equipo.sql:62; operacion.ts:99. Ejemplo calendario es deducción, no ensayo con reloj de base simulado.'},
{id:'MC04',p:'P1',area:'Reglas e integridad',estado:'Reproducido',title:'La preventa de 48 horas no está garantizada por la app',problem:'Una experiencia recién creada aparece en el catálogo y se puede comprar sin Mesa Fundadora. No hay campos de apertura exclusiva/general ni autorización de preventa. El texto atribuye esta ventaja al personal.',impact:'La ventaja pagada no se distingue en el recorrido digital. Una preventa manual externa podría existir, pero no fue acreditada.',fix:'Definir apertura para miembros y público, responsable del anuncio y cupos. Validar el acceso en servidor. Si la promesa es manual, describir y registrar el procedimiento efectivamente ofrecido.',accept:'Durante las 48 horas exclusivas, fundador elegible compra y cliente gratuito recibe fecha de apertura; llamadas directas a la API respetan lo mismo.',owner:'Dirección + operación + backend',evidence:'T05; Club.tsx:41; index.ts:399,914; db/001_schema.sql:169.'},
{id:'MC05',p:'P2',area:'Estados y fiabilidad',estado:'Reproducido y revisión de código',title:'Volver a Mi Club conserva datos anteriores a la entrega',problem:'Tras registrar una entrega sintética en caja y navegar a Inicio y de vuelta, la pantalla seguía diciendo Disponible hoy. El proveedor refresca al montar o por acciones concretas, sin foco, reconexión ni cambio de ventana.',impact:'El cliente ve derechos, sellos o saldo desactualizados. El servidor impide el doble uso, pero la pantalla invita a acciones que fallarán; al cambiar de día también puede ocultar un derecho nuevo.',fix:'Actualizar al volver a la sección o recuperar foco, tras entrega y en límites temporales informados por servidor. Incluir Actualizar y última consulta. No habilitar derechos solo por el reloj del dispositivo.',accept:'Entrega en caja → retomar app refleja el cambio. Medianoche, cambio de mes y reconexión actualizan el derecho; datos viejos se identifican y pueden recuperarse.',owner:'Frontend + backend',evidence:'Prueba UI «Beneficios con datos sin refrescar» en Edge y Firefox; datos.tsx:403–439; Club.tsx:335.'},
{id:'MC06',p:'P2',area:'Estados y fiabilidad',estado:'Reproducido',title:'El beneficio renovable depende del orden de las consultas',problem:'Con renovación consentida y saldo suficiente, una membresía recién vencida obtuvo 403 al pedir café. Después de consultar /yo obtuvo 200. El mantenimiento programado es horario.',impact:'Una persona elegible puede recibir una negativa si dejó la pantalla abierta al vencer y aún no pasó el mantenimiento.',fix:'Resolver la transición y el derecho de forma coherente e idempotente antes de solicitar el beneficio; distinguir renovación en curso, vencimiento y falta de saldo.',accept:'El mismo contrato da el mismo resultado antes/después del cron y con/sin consulta previa de /yo, sin doble débito.',owner:'Backend',evidence:'T02; operacion.ts:90; index.ts:446; wrangler.jsonc:10.'},
{id:'MC07',p:'P2',area:'Arquitectura y seguridad',estado:'Reproducido',title:'Leer la cuenta puede cobrar; contratar puede renovar a otras personas',problem:'GET /yo ejecuta mantenimiento y debitó C$950 en una renovación consentida. El alta de A ejecuta mantenimiento global y también cobró a B. La segunda lectura no duplicó el cargo.',impact:'Lecturas y escrituras monetarias quedan acopladas; el alta depende de trabajo ajeno y la recuperación ante fallos resulta más difícil. No se reprodujo cobro sin consentimiento.',fix:'Devolver una proyección de lectura y ejecutar renovaciones en un proceso explícito, acotado por socio, con idempotencia, recibo y resultado individual. Conservar bloqueos e índices.',accept:'Repetir GET no cambia libro, puntos o membresía. Un fallo en B no bloquea la consulta/alta de A. Un período tiene un solo cargo.',owner:'Backend + operación técnica',evidence:'T01,T12; index.ts:446,803,1170; RFC 9110 §9.2.1.'},
{id:'MC08',p:'P2',area:'Canje y operación',estado:'Reproducido',title:'El código promete diez minutos aunque pueden quedar segundos',problem:'Reabrir un código vigente devuelve el mismo vencimiento original. La prueba dejó treinta segundos y la interfaz mantuvo el texto Vence en diez minutos. El vale de sellos dura noventa segundos y el componente descarta su vencimiento.',impact:'La persona puede llegar a caja con un código vencido creyendo que aún sirve. Cerrar/abrir no reinicia necesariamente su vigencia.',fix:'Mostrar hora o tiempo restante real con referencia del servidor, estado vencido y Generar otro. Calcular fin efectivo según código, ventana y membresía. Confirmar visualmente la entrega.',accept:'Reabrir al minuto 9:30 muestra unos treinta segundos, no diez minutos nuevos. Expirar no consume premio y regenerar conserva el derecho.',owner:'Frontend + backend',evidence:'T09; operacion.ts:104,117; index.ts:611; Club.tsx:474–483.'},
{id:'MC09',p:'P1',area:'Accesibilidad',estado:'Reproducido en dos motores',title:'Cerrar el código pierde el foco del control de origen',problem:'En Edge y Firefox, el diálogo abre con foco en Cerrar; después de Escape y del cierre efectivo, document.activeElement es BODY. El disparador se deshabilita durante la solicitud anterior a la apertura.',impact:'Quien usa teclado o lector pierde su punto de trabajo. Que el diálogo sea nativo no garantiza este retorno cuando su disparador cambia de estado.',fix:'Guardar el control que inició el flujo antes de la petición y restaurar foco al cerrar; si desaparece, enfocar un encabezado o acción equivalente. Probar además el cierre con botón y tras entrega.',accept:'Abrir → Escape, Cerrar y Actualizar vuelve a un destino útil en ambas plataformas; la siguiente tabulación continúa en el contexto del beneficio.',owner:'Frontend + calidad',evidence:'UI «Generar código no consume beneficio y hay foco modal»: focusReturn.tag=BODY; Superficies.tsx:215; Club.tsx:136. APG diálogo modal.'},
{id:'MC10',p:'P1',area:'Accesibilidad',estado:'Reproducido bajo ampliación sintética',title:'El pase pierde contenido cuando el texto necesita más altura',problem:'Al duplicar los tamaños calculados de texto y line-height a 390 px, la cara del pase tiene 374 px de alto y 641 px de contenido. Los sellos y la identificación quedan fuera de su caja. No hay scroll horizontal, por lo que comprobar solo el ancho no detecta el fallo.',impact:'Personas que amplían texto pueden perder la identificación y la lectura del progreso. En las filas de beneficios el título queda excesivamente comprimido entre icono y botón.',fix:'Permitir altura intrínseca; usar capas de grid o identificación estática con ayuda desplegable. En pantallas estrechas, poner el botón del beneficio debajo del texto.',accept:'Texto al 200 %, nombre largo y espaciado WCAG conservan todo el contenido sin solapamiento; validar además zoom de navegador y lector/dispositivo real. No basta axe ni scrollWidth.',owner:'Frontend + diseño + calidad',evidence:'UI «Texto calculado duplicado»: clientHeight374/scrollHeight641 en Edge; evidencia-ui/texto-calculado-200-edge.png. La simulación no equivale a certificación con tecnología asistiva real.'},
{id:'MC11',p:'P2',area:'Diseño y jerarquía',estado:'Medido',title:'La composición retrasa el acceso a lo que el miembro puede usar',problem:'Con miembro activo, Lo tuyo de este mes comienza en y=1.863 px a 390×844 y en y=1.116 a 1440×960. La apertura prioriza un pase grande, dos representaciones del mismo progreso, textos aspiracionales y otra invitación a reservar.',impact:'En caja hay que desplazarse bastante antes de encontrar el café o la bolsa. Es una fricción medida en geometría, no una tasa de abandono demostrada.',fix:'Colocar derechos disponibles y próxima acción arriba. Conservar la identidad y el pase en formato compacto; mostrar un solo progreso. Reservas y experiencias pasan a una zona secundaria.',accept:'En 390×844 se identifica y activa el beneficio disponible con cero o un desplazamiento corto. Prueba moderada de tarea en caja con tiempos y errores.',owner:'Diseño + producto',evidence:'Posiciones y capturas activa-390/activa-1440 en resultados-edge.json. No hay entrevistas ni datos de conversión.'},
{id:'MC12',p:'P1',area:'Propuesta comercial',estado:'Reproducido y código',title:'La persona que va a pagar no ve todos los beneficios',problem:'Los cinco beneficios detallados se renderizan solo cuando ya existe membresía. La oferta sin membresía menciona bolsa y café, pero omite gramaje, descuento, prioridad y la ventaja de experiencias.',impact:'La evaluación de valor se hace con información incompleta justo antes de decidir si pagar C$950.',fix:'Crear una oferta completa para no miembros: gratis frente a Mesa Fundadora, cinco beneficios, límites, cuota/ciclo, forma de pago y cancelación. Para miembros, mostrar uso y disponibilidad.',accept:'Sin contratar, una persona puede explicar todo lo incluido, restricciones, renovación y cancelación. Verificar con usuarios nuevos; no mostrar derechos pagados como disponibles.',owner:'Producto + diseño + dirección',evidence:'UI «Sin membresía con saldo insuficiente», beneficiosDetalladosVisibles=0; Club.tsx:246–249,306–359.'},
{id:'MC13',p:'P2',area:'Conversión y recuperación',estado:'Reproducido',title:'Falta de saldo deja un botón inactivo sin salida contextual',problem:'Mi Club muestra cuánto falta, pero no saldo actual ni una acción de recarga junto a la oferta. La prueba con cero saldo encontró la compra deshabilitada y cero botones de recarga en el contenido. La recarga sí existe en Inicio/Perfil.',impact:'Quien quiere contratar o comprar una experiencia debe descubrir otra sección y reconstruir su intención.',fix:'Mostrar saldo, faltante y Cómo recargar. Explicar que la operación actual se hace en caja y mantener el destino original para volver tras actualizar saldo.',accept:'Saldo cero/parcial permite conocer el paso siguiente en la misma pantalla, llegar a recarga y regresar a la oferta sin cobro automático.',owner:'Producto + frontend',evidence:'Club.tsx:274–289,415–431; Inicio.tsx:145,184–222; Perfil.tsx:191.'},
{id:'MC14',p:'P2',area:'Estados y fiabilidad',estado:'Reproducido',title:'La confirmación se cierra antes de resolver la compra',problem:'Con una respuesta detenida artificialmente, la hoja ya estaba cerrada. El botón de origen conserva aria-busy, pero la región viva seguía anunciando la cancelación anterior y no el procesamiento actual.',impact:'Se reduce la claridad entre enviado, completado, rechazado y resultado incierto. En renovación no queda un indicador local equivalente.',fix:'Mantener importe y operación en contexto hasta resolver; comunicar procesamiento y error junto al control. Si el usuario cierra, conservar operación pendiente consultable. Tratar incertidumbre antes de ofrecer otra compra.',accept:'Con latencia, 500 y desconexión, siempre se conoce el estado y la acción segura; una referencia reintentada no duplica el cargo.',owner:'Frontend + backend',evidence:'UI «Compra experiencia durante respuesta pendiente»; Club.tsx:111–118; pedirJSON ya distingue resultado incierto.'},
{id:'MC15',p:'P2',area:'Estados y fiabilidad',estado:'Reproducido y código',title:'El éxito previo permanece sin poder descartarse',problem:'hecho nunca se limpia en Club y el aviso no recibe acción de cierre. Tras cancelar renovación, el mismo mensaje seguía durante otra compra pendiente. Es una capa fija sobre el contenido.',impact:'Puede confundirse el resultado de dos operaciones y ocupar espacio de lectura. No se confirmó una obstrucción específica de foco en todos los tamaños.',fix:'Guardar confirmación junto al estado/recibo, permitir descartar el aviso flotante y retirar el resultado anterior al comenzar otra acción. Anunciar cada operación por identificador, aunque repita texto.',accept:'Éxito → operación siguiente → fallo deja un mensaje inequívoco de la última operación y un historial recuperable; el aviso puede cerrarse.',owner:'Frontend',evidence:'UI cancelación y compra pendiente; Club.tsx:65,117,528; Estados.tsx:296–337.'},
{id:'MC16',p:'P2',area:'Confianza y trazabilidad',estado:'Reproducido',title:'La renovación carece de un historial duradero de decisiones',problem:'Cancelar y reactivar cambian la fila, pero el ensayo no encontró eventos de auditoría ni avisos; renovacion_consentida guarda un timestamp sobrescrito. La explicación y consentimiento inicial sí existen.',impact:'Soporte y cliente tienen menos evidencia ante una duda sobre cuándo cambió la renovación y bajo qué condiciones.',fix:'Registrar eventos inmutables con actor, fecha efectiva, importe, versión de condiciones y referencia. Mostrar comprobante consultable de activación/cancelación.',accept:'Activar → cancelar → activar produce tres eventos y un estado inequívoco. El reintento no duplica la decisión ni borra historia.',owner:'Backend + producto',evidence:'T07; index.ts:846; Club.tsx:487,519.'},
{id:'MC17',p:'P2',area:'Retención y estados',estado:'Reproducido',title:'El vencimiento devuelve a la oferta genérica sin explicar la recuperación',problem:'Sin saldo, la membresía vence; recargar después no la reactiva. La interfaz recibe membresia:null y muestra la venta como a un nuevo prospecto. Persiste código/copy para en_gracia, pero no hay gracia en la transición actual probada.',impact:'No se distingue cancelación voluntaria de fallo de renovación ni se explica qué pasó con la plaza y los beneficios.',fix:'Conservar estado histórico resumido, motivo, período terminado, saldo requerido y acción de reingreso. Recordar renovación de forma consentida; aclarar el riesgo de perder plaza. No introducir deuda ni gracia implícita.',accept:'Cada causa tiene explicación y siguiente paso. Recargar no se presenta como reactivación automática si el servidor exige una nueva contratación.',owner:'Producto + backend',evidence:'T08; UI «Estado en gracia servido por la API»; db/018_clientes_equipo.sql:59–61; Club.tsx:519.'},
{id:'MC18',p:'P2',area:'Experiencias y operación',estado:'Reproducido con cesión sintética en base',title:'La entrada cedida no aparece para su destinatario',problem:'El modelo admite cedido_a y caja lo usa como asistente, pero /compras devuelve la entrada al comprador original. El destinatario recibió una lista vacía. No se encontró un flujo operativo de cesión completo.',impact:'La persona invitada no tiene comprobante visible aunque el modelo la reconozca como titular de asistencia.',fix:'Separar recibo del comprador y entrada del titular actual; transferencia asistida, auditada y consultable por ambos, sin exponer datos de terceros.',accept:'A compra y cede a B: A conserva recibo cedido, B ve butaca vigente, caja recibe a B, y no se puede transferir tras asistencia.',owner:'Backend + operación + producto',evidence:'T06; operacion.ts:40; mostrador.ts:34; Club.tsx:505. La cesión se sembró en base, no se fingió un autoservicio existente.'},
{id:'MC19',p:'P2',area:'Experiencias y recuperación',estado:'Reproducido y revisión de contenido',title:'La compra termina sin un acceso directo a la entrada',problem:'Después de apartar, el éxito informa butaca y saldo, pero no ofrece Ver entrada o Mis compras desde Mi Club. El historial existe en Perfil. Antes de comprar solo se ven nombre, fecha, precio y cupos; faltan descripción y logística estructuradas.',impact:'Cuesta recuperar el comprobante y decidir con información suficiente; no se aclara bien qué sucede si la casa cancela o cambia la experiencia.',fix:'Añadir detalle previo y confirmación persistente con enlace a la entrada, hora/lugar, titular, butaca y ayuda. Definir reprogramación/cancelación por la casa y su comunicación.',accept:'Compra → entrada consultable → retorno tras recarga de página sin repetir compra. Se entiende lugar, duración, inclusiones y condiciones antes de confirmar.',owner:'Producto + frontend + operación',evidence:'UI compra: enlaceCompra=0/botonCompra=0; Club.tsx:148–154,381–433,505; Perfil.tsx:242.'},
{id:'MC20',p:'P2',area:'Sellos e integridad',estado:'Reproducido',title:'Un ticket con espacios externos puede otorgar otro sello',problem:'La API valida ticket.trim(), pero guarda el original. ticket y el mismo ticket con espacios acreditaron dos sellos. Requiere acceso del personal; el socio no puede autoacreditarse.',impact:'Duplicación por entrada manual y menor confiabilidad del programa. No demuestra abuso por clientes ni integración real con POS.',fix:'Normalizar la referencia antes de comparar y guardar; acordar identidad con caja/POS. Diferenciar reintento propio de ticket asociado a otra cuenta sin divulgar sus datos.',accept:'Variantes solo de espacios externos tienen un único sello. El reintento recupera el resultado y el conflicto ajeno se explica.',owner:'Backend + caja',evidence:'T10; index.ts:531,545; CajaCliente.tsx:14.'},
{id:'MC21',p:'P2',area:'Operación comercial',estado:'Código; práctica externa no observada',title:'Los beneficios asistidos y las listas de espera necesitan un proceso verificable',problem:'El 15 %, prioridad VIP y avisos de cupos se delegan a la barra. No se define acumulación, canal, responsable, prueba de inscripción o corrección de entrega. El cobro digital por líneas no calcula automáticamente el 15 % por membresía.',impact:'La experiencia puede variar por turno y el cliente no sabe si su solicitud quedó anotada. No se puede concluir que la caja externa no aplique el descuento.',fix:'Ficha de reglas para cliente y personal, descuento visible en recibo, cola de espera con consentimiento y estado, responsable y plazo. Prioridad VIP no desplaza reservas confirmadas. Corregir entregas con un evento de ajuste motivado.',accept:'Dos turnos resuelven igual el mismo caso; una espera tiene alta/fecha/baja comprobables; agotado no consume beneficio y tiene alternativa acordada.',owner:'Dirección + operación',evidence:'Club.tsx:39–41,268–269,354–356,410–414; findings_tecnica.md decisiones 5,6,8.'},
{id:'MC22',p:'P2',area:'Contenido y comprensión',estado:'Código confirmado',title:'Faltan reglas de uso y precisión en fechas y horarios',problem:'No se explica qué compra gana sello, qué bebida incluye el premio o qué significa retiro de 7 a 9. Frases encadenadas omiten puntuación. fechaCorta no fija America/Managua aunque las ventanas de derechos sí lo hacen.',impact:'La marca requiere explicaciones de caja para reglas básicas; quien viaja puede ver una fecha de renovación distinta al día de la casa.',fix:'Añadir reglas breves junto al progreso y beneficio; indicar a. m./p. m., local, fecha de entrega y próxima habilitación. Usar zona de Managua para fechas comerciales y puntuar conservando el voseo.',accept:'Usuarios nuevos responden correctamente cómo ganar y usar el premio y cuándo retirar. Una misma fecha de servidor muestra el día comercial acordado en distintos husos.',owner:'Contenido + operación + frontend',evidence:'Club.tsx:175,316,335,481; datos.tsx:469. El riesgo de huso se deduce de Intl sin timeZone; no hubo ensayo en dispositivo viajero.'},
{id:'MC23',p:'P2',area:'Concurrencia y capacidad',estado:'Riesgo deducido; pendiente PostgreSQL multiconexión',title:'Dos compradores pueden competir por la primera butaca y recibir un falso agotado',problem:'Cada comprador bloquea su socio, elige la primera butaca libre e inserta con ON CONFLICT DO NOTHING. Una colisión no reintenta la siguiente butaca. El índice evita sobreventa, pero no demuestra que todas las libres se asignen correctamente bajo simultaneidad.',impact:'Posible rechazo aun con otras butacas libres. Las pruebas secuenciales pasaron; no se midió frecuencia ni se confirmó con varias conexiones.',fix:'Bloqueo por experiencia con orden consistente, butacas precreadas con reserva transaccional o reintento acotado; conservar cargo atómico y referencia idempotente.',accept:'En PostgreSQL aislado, doce compradores simultáneos obtienen doce butacas distintas y doce cargos; el decimotercero obtiene agotado. Probar también cancelación/renovación concurrentes.',owner:'Backend + calidad',evidence:'index.ts:923; documentación PostgreSQL sobre READ COMMITTED y ON CONFLICT. No es prueba de sobreventa.'},
{id:'MC24',p:'P2',area:'Gobierno del producto',estado:'Código y documentación',title:'No hay una definición comercial única y versionada',problem:'La cuota actual del catálogo es C$950; SPEC conserva C$400 en parte de sus instrucciones y reconoce el conflicto. Comentarios aún describen estilos anteriores. Un componente concentra presentación, reglas derivadas y múltiples transacciones.',impact:'Cambios futuros pueden reintroducir contratos distintos pese a pasar pruebas. No se observó cobro diferente al importe confirmado en la UI.',fix:'Ficha aprobada de precio, ciclo, derechos y cancelación con versión; contrato API compartido; componentes de membresía, derechos y experiencias con límites claros; suite dedicada a los casos de esta auditoría.',accept:'Una modificación de regla actualiza contrato, UI, caja, documentación y pruebas de frontera. La cuota individual histórica se migra según una decisión explícita.',owner:'Dirección + producto + ingeniería',evidence:'Catálogo público y index.ts:89,431; SPEC.md:252,275; Club.tsx; comentarios de Superficies.tsx.'},
{id:'MC25',p:'P2',area:'Economía y medición',estado:'Brecha de evidencia comercial',title:'Falta demostrar contribución incremental y dónde se abandona el recorrido',problem:'No se dispuso de costos, cohortes ni analítica de eventos de Mi Club. La cuota debitada puede consumir bonos; no equivale a efectivo nuevo. Los registros operativos existentes no explican por sí solos intención, comprensión o abandono.',impact:'No puede concluirse rentabilidad, precio óptimo ni incremento de retención. Optimizar clics puede aumentar entregas costosas sin aumentar margen.',fix:'Medir activación, primer canje, renovación por causa, adopción de cada beneficio, costo y compras incrementales. Separar dinero aportado, bono, saldo utilizado y contribución.',accept:'Dirección puede conciliar cobros y entregas con costos y distinguir renovación fallida de voluntaria; eventos de conversión no incluyen códigos ni datos personales innecesarios.',owner:'Dirección + finanzas + producto',evidence:'db/015_saldo_cronologico.sql:30–34; findings_comercial.md economía y medición. Ninguna estimación de margen fue inventada.'},
{id:'MC26',p:'P2',area:'Privacidad y confianza',estado:'Revisión de superficie; requiere validación de políticas',title:'Hacer verificables las condiciones, ayuda y uso de datos del programa',problem:'La contratación muestra precio y renovación, pero no un resumen versionado de todas las condiciones del Club ni un acceso contextual a dudas/canje fallido. El pase gratuito muestra los últimos ocho dígitos de teléfono como identificación; el token de cliente se conserva en localStorage.',impact:'Hay exposición de contacto al mostrar el pase y dependencia de proteger el origen frente a scripts maliciosos. No se reprodujo robo de sesión ni acceso entre cuentas. Las políticas y prácticas externas no fueron auditadas.',fix:'Identificador público específico en el pase; no registrar códigos/tokens en analítica; condiciones accesibles, canales y responsables de reclamo. Validar retención, exportación/baja y consentimiento separado para recordatorios/marketing con las políticas del negocio.',accept:'Pase útil sin teléfono expuesto; eventos sin secretos; condiciones aceptadas recuperables; ayuda contextual con referencia y resultado. Revisar además seguridad de sesión como decisión global de la app.',owner:'Producto + seguridad + dirección',evidence:'Club.tsx:174; sesion-cliente.ts:10–21; ausencia de enlace de condiciones en confirmación; MIFIC sobre transparencia de precios/promociones. No es dictamen de cumplimiento legal integral.'},
{id:'MC27',p:'P3',area:'Rendimiento',estado:'Tamaño medido; experiencia de campo pendiente',title:'Medir rendimiento de la tarea además del tamaño del paquete',problem:'La compilación entrega 415.080 bytes de JavaScript principal (129,27 kB gzip estimados por Vite) y 73.931 bytes de CSS. Club se importa con otras pantallas; el panel de personal sí es diferido. No se midieron Core Web Vitals de visitantes reales.',impact:'Hay un candidato de optimización, pero el tamaño por sí solo no prueba lentitud en la clientela. La mayor demora observada de uso es encontrar la acción.',fix:'Medir LCP/INP/CLS por dispositivo y red, tiempo hasta beneficio utilizable y errores de API. Evaluar división de rutas e imágenes/fuentes solo si las mediciones justifican el costo.',accept:'Objetivos propuestos de campo p75: LCP≤2,5s, INP≤200ms y CLS≤0,1; sin degradar canje ni recuperación en red lenta. Reportar muestra y contexto.',owner:'Frontend + observabilidad',evidence:'Build aislado, evidencia-publica.json (hash idéntico de JS/CSS), App.tsx imports; web.dev umbrales oficiales.'},
{id:'MC28',p:'P3',area:'Navegación y semántica',estado:'Código confirmado',title:'Nombres, acciones repetidas y el pase pueden orientarse mejor',problem:'Se alternan Mi Club, Club y El Club. Los dos botones de beneficio se llaman Mostrar código; todas las experiencias Apartar butaca. El pase cambia etiqueta mientras conserva aria-pressed. Navegación por botones no ofrece funciones de enlaces.',impact:'Se requiere más contexto al usar listado de controles, voz, historial o pestañas; el destino se identifica de forma inconsistente.',fix:'Nombre Mi Club y título de página consistente; botones Código de mi café / Código de mi bolsa; experiencia en nombre accesible; ayuda del pase desplegable o botón ordinario; enlaces para destinos.',accept:'Lista de controles permite distinguir cada acción, los destinos se pueden abrir/copiar como enlaces y el pase anuncia estado sin contradicción.',owner:'Frontend + contenido',evidence:'Navegacion.tsx:23,41,78; PaseSocio.tsx:24; Club.tsx:81,167,321,339,416; index.html:7. APG botón.'}
]
const e=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')
const rows=(heads,data)=>`<div class="table-wrap"><table><thead><tr>${heads.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${data.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`
const section=(id,title,body)=>`<section id="${id}"><h2>${title}</h2>${body}</section>`
const counts=Object.fromEntries(['P1','P2','P3'].map(p=>[p,findings.filter(f=>f.p===p).length]))
