const cards=findings.map(f=>`<article class="finding" data-priority="${f.p}" data-search="${e((f.id+' '+f.area+' '+f.title+' '+f.problem).toLowerCase())}" id="${f.id}"><div class="finding-top"><span class="pill ${f.p}">${f.p}</span><span>${f.id} · ${e(f.area)}</span></div><h3>${e(f.title)}</h3><p class="status">${e(f.estado)}</p><p>${e(f.problem)}</p><p><strong>Consecuencia.</strong> ${e(f.impact)}</p><details><summary>Mejora, aceptación y evidencia</summary><p><strong>Mejora propuesta.</strong> ${e(f.fix)}</p><p><strong>Criterio de aceptación.</strong> ${e(f.accept)}</p><p><strong>Responsable.</strong> ${e(f.owner)}</p><p class="evidence"><strong>Evidencia.</strong> ${e(f.evidence)}</p></details></article>`).join('')
let body=`<header><p class="eyebrow">LA BELLA LUPITA · AUDITORÍA DE PRODUCTO</p><h1>Mi Club<br><em>Diagnóstico integral</em></h1><p class="lead">La base visual y los controles principales son aprovechables. La mejora de mayor valor es convertir Mi Club en una pantalla de derechos claros y acciones inmediatas, respaldada por reglas idénticas en la oferta, el servidor y caja.</p><p>8 de octubre de 2026 · America/Managua · Auditoría y propuesta; sin cambios funcionales ni publicación.</p><div class="stats"><div><b>${findings.length}</b><span>hallazgos y oportunidades</span></div><div><b>${ui.results.length} × 2</b><span>escenarios UI, Edge y Firefox</span></div><div><b>${tec.resultados.length}</b><span>escenarios técnicos aislados</span></div><div><b>0</b><span>violaciones axe en estados auditados*</span></div></div><p class="small">*19 comprobaciones por motor. Las pruebas también reproducen defectos: ejecutar un escenario con éxito no significa que el producto esté libre de fallos. Axe no detectó la pérdida de foco ni certifica accesibilidad integral.</p></header>
<nav class="report-nav" aria-label="Secciones del informe"><a href="#dictamen">Dictamen</a><a href="#alcance">Evidencia</a><a href="#hallazgos">28 hallazgos</a><a href="#propuesta">Propuesta</a><a href="#reglas">Decisiones</a><a href="#ruta">Prioridades</a><a href="#economia">Medición</a><a href="#fuentes">Fuentes</a><button onclick="window.print()">Imprimir</button></nav>`
body+=section('dictamen','Qué conviene resolver primero',`<div class="callout"><p><strong>Hay siete prioridades P1 antes de intensificar la venta del plan:</strong> topes coherentes; promesa de café; ciclo de cuota y bolsa; acceso anticipado; retorno de foco; pase con texto ampliado; oferta completa antes de pagar. P1 indica impacto en el contrato o acceso esencial, no una emergencia de seguridad. No se confirmó un incidente P0.</p></div><p>El Club gratuito y la Mesa Fundadora tienen un propósito comprensible, pero comparten una pantalla que mezcla presentación de marca, sellos, venta, administración, canjes, experiencias y reservas. La identidad cálida funciona; la jerarquía da demasiado espacio al mensaje y al pase antes de llegar a los beneficios utilizables.</p><p>La primera tarea del módulo debería ser responder <strong>qué tengo disponible ahora, cómo lo uso y qué ocurrirá con mi membresía</strong>. Para quien aún no paga, debe responder qué incluye la oferta, cuánto cuesta, cada cuánto se cobra y cómo se cancela. Hoy esas respuestas están dispersas o incompletas.</p>${rows(['Perspectiva','Diagnóstico','Dirección de mejora'],[
['Cliente nuevo','Diferencia gratis/pago y valor completo insuficientemente expuestos.','Comparación breve y reglas antes de la contratación.'],['Miembro en caja','Beneficios profundos, vigencia del código imprecisa y datos que pueden quedar viejos.','Acciones disponibles arriba, vencimiento real y confirmación de entrega.'],['Cliente que cancela o vuelve','El cambio funciona, pero faltan comprobante y recuperación contextual.','Historia de decisiones, motivo de vencimiento y reingreso explícito.'],['Caja y atención','Controles de entrega sólidos; reglas asistidas y excepciones poco formalizadas.','Manual breve por beneficio, trazabilidad y corrección con motivo.'],['Dirección y finanzas','Se conoce cuota nominal; falta demostrar costo y resultado incremental.','Cohortes, uso, bonos, contribución y carga operativa.'],['Accesibilidad','Buena base semántica y contraste; problemas de foco y expansión de contenido.','Corregir interacciones y probar con tecnologías asistivas reales.'],['Ingeniería y seguridad','Transacciones e idempotencia presentes; lifecycle y contrato de derechos fragmentados.','Modelo único de derechos, lecturas sin cobros y ensayos de concurrencia.']])}`)
body+=section('alcance','Qué se revisó y qué quedó demostrado',`<p>Se inspeccionaron la captura aportada, la ruta pública, el código actual del cliente, componentes compartidos, Worker, migraciones, pruebas y documentación local. La captura del usuario solo muestra el menú: no demuestra una pantalla de contenido en blanco.</p><p>La lectura pública de <a href="https://app.labellalupita.com/club">/club</a>, <a href="https://app.labellalupita.com/api/catalogo">catálogo</a> y <a href="https://app.labellalupita.com/api/cupos">cupos</a> devolvió 200. En ese momento el catálogo declaraba <strong>C$950, cien plazas y ninguna experiencia futura</strong>; cupos indicaba cien plazas disponibles. Son una observación puntual, no una serie de demanda. Las experiencias de las capturas de prueba son sintéticas.</p><p>Los archivos principales publicados de JavaScript y CSS son idénticos byte a byte a la compilación local. Esto vincula la revisión visual con el frontend publicado; <strong>no certifica la versión del Worker remoto ni sus migraciones o configuración</strong>. La pantalla autenticada se probó en local con datos sintéticos y SQL real de PGlite. No se compró ni se canjeó en producción.</p>${rows(['Comprobación','Resultado','Límite'],[
['TypeScript y compilación aislada','npm run check y vite build completados.','No se ejecutó un despliegue.'],['Suite existente','npm test completo: diez archivos de suite terminaron con código 0.','Que pasen no cubre todos los bordes de este informe.'],['UI específica','17 escenarios en Edge '+e(ui.version)+' y Firefox '+e(ff.version)+'; sin errores de página registrados.','34 ejecuciones; verifican comportamientos correctos y defectos.'],['Adaptación','320, 390, 768, 1024 y 1440 px; sin scroll horizontal de página en las muestras.','Ausencia de desborde horizontal no implica ausencia de contenido recortado.'],['Accesibilidad automática','19 muestras axe por motor, sin violaciones en los estados auditados.','Ampliación calculada se inspeccionó visualmente; no se corrió axe sobre estilos artificiales.'],['Backend específico','14 escenarios secuenciales reproducibles en memoria.','No simulan varias conexiones PostgreSQL, cron remoto ni carga real.'],['Investigación','Programas oficiales, W3C, PostgreSQL, RFC, OWASP, web.dev y MIFIC.','Los referentes no prueban preferencias, rentabilidad o cumplimiento de este negocio.']])}<p><strong>No se realizaron</strong> entrevistas, observación de caja física, NVDA/VoiceOver en dispositivos reales, auditoría fiscal/legal integral, pentest exhaustivo, prueba de restauración, ensayo remoto de concurrencia ni medición de campo de rendimiento. Estos límites acompañan las conclusiones afectadas.</p><div class="gallery"><figure><a href="evidencia-ui/activa-1440-edge.png"><img src="evidencia-ui/activa-1440-edge.png" alt="Mi Club de escritorio con beneficios debajo de la apertura" loading="lazy"></a><figcaption>Escritorio · los beneficios comienzan en y=1.116 px.</figcaption></figure><figure><a href="evidencia-ui/activa-390-edge.png"><img src="evidencia-ui/activa-390-edge.png" alt="Recorrido móvil de Mi Club con beneficios a gran profundidad" loading="lazy"></a><figcaption>Móvil 390×844 · beneficios en y=1.863 px. Las barras fijas aparecen a la altura del viewport en la captura completa.</figcaption></figure><figure><a href="evidencia-ui/texto-calculado-200-edge.png"><img src="evidencia-ui/texto-calculado-200-edge.png" alt="Texto ampliado con desborde vertical de la tarjeta del pase" loading="lazy"></a><figcaption>Texto calculado al doble · contenido de 641 px dentro de una cara de 374 px.</figcaption></figure></div>`)
body+=section('fortalezas','Qué ya funciona y conviene conservar',`<ul><li>Precio de contratación leído del servidor y confirmación con costo, saldo disponible y remanente.</li><li>Dinero en centavos, libro mayor inmutable, referencias de compra idempotentes y saldo suficiente antes de cobrar.</li><li>Código separado del derecho: mostrarlo no consume la bolsa o el premio; el personal confirma la entrega y el segundo uso se rechaza.</li><li>Autorización y aislamiento: un cliente no entrega beneficios ni accede al historial de otro en los casos ensayados.</li><li>Ventanas diarias y mensuales calculadas en Managua, preservación de premios al caducar el vale y cancelación sin quitar el período ya pagado.</li><li>Diálogo nativo, enlace de salto, regiones vivas, movimiento reducido, botones amplios y contraste de texto principal adecuado.</li><li>Una identidad reconocible: retrato, tonos cálidos, tipografía y voseo pueden conservarse al simplificar la pantalla.</li></ul><p>No hay evidencia en estas pruebas de doble débito al repetir la misma referencia, sobreventa secuencial o beneficio consumido por el mero acto de mostrar su código. Las recomendaciones parten de esta base.</p>`)
body+=section('hallazgos','Hallazgos priorizados',`<p>${counts.P1} P1 · ${counts.P2} P2 · ${counts.P3} P3. P2 afecta fiabilidad, operación o recuperación; P3 optimiza una base funcional. Cada tarjeta distingue reproducción, código, inferencia o información pendiente.</p><div class="filters"><label>Prioridad <select id="priority"><option value="all">Todas</option><option>P1</option><option>P2</option><option>P3</option></select></label><label>Buscar <input id="search" type="search" placeholder="Ejemplo: renovación, foco, caja"></label><button id="expand">Abrir todos los detalles</button></div><p id="resultCount" role="status">${findings.length} hallazgos visibles</p><div id="findings">${cards}</div>`)
body+=section('propuesta','Estructura propuesta para Mi Club',`<p>La estructura siguiente es un diagnóstico de arquitectura de información, no un rediseño aplicado. Debe variar según la relación del cliente y el estado real de cada derecho.</p><div class="proposal"><div class="proposal-head"><strong>Mi Club</strong><span>Datos actualizados · Actualizar</span></div><div class="proposal-row"><b>Para usar ahora</b><p>Café disponible · Bolsa disponible · Premio ganado</p><small>Mostrar solo acciones a las que la persona tiene derecho. Botones con nombre específico.</small></div><div class="proposal-row"><b>Tu progreso</b><p>8 de 9 sellos · Te falta 1</p><small>Un contador, cómo ganar sellos, historial y ayuda si falta uno.</small></div><div class="proposal-row"><b>Tu Mesa Fundadora</b><p>Estado · próxima fecha · cuota por período · saldo para renovar</p><small>Administrar renovación, consultar condiciones y comprobantes. Si no es miembro: oferta completa.</small></div><div class="proposal-row"><b>Experiencias y tus entradas</b><p>Disponibilidad real · acceso anticipado cuando corresponda</p><small>Detalle del evento, compra, comprobante y transferencia asistida.</small></div><div class="proposal-row"><b>Tu próxima visita</b><p>Un acceso a reservar mesa y ayuda del Club</p><small>El pase queda accesible desde la cabecera o una sección compacta.</small></div></div>${rows(['Estado de persona','Primer bloque','Acción principal'],[
['Club gratuito sin premio','Progreso y cómo ganar el próximo sello.','Ver reglas / identificarme en caja.'],['Club gratuito con premio','Bebida de cortesía disponible y condiciones.','Mostrar código del premio.'],['Mesa activa','Café/bolsa disponibles con próxima ventana.','Código del café o de la bolsa.'],['Mesa activa sin renovación','Derechos hasta fecha exacta; renovación apagada.','Usar lo pagado / administrar.'],['Renovación fallida por saldo','Motivo y siguiente paso explícitos.','Cómo recargar / revisar reingreso.'],['Sin membresía, interesado','Club gratis frente a oferta completa de Mesa.','Revisar contratación o recarga.'],['Datos sin conexión','Última consulta y derechos pendientes de validar.','Reintentar; no prometer canje offline.']])}<p><strong>Criterios visuales:</strong> conservar el sistema de marca, reducir la altura del bloque de presentación, unificar sellos, retirar duplicación de reservas, y usar disposición vertical de texto y acción cuando una fila estrecha deje de ser legible. El elemento de mayor énfasis debe corresponder al siguiente paso útil del cliente.</p>`)
body+=section('reglas','Decisiones que debe cerrar el negocio',`${rows(['Decisión','Situación actual','Resultado que debe aprobarse'],[
['Cuota y duración','C$950 vigente; período de 30 días; documentación con C$400.','Precio autorizado, impuestos incluidos cuando corresponda, periodicidad y tratamiento de contratos anteriores.'],['Bolsa','250 g; mes calendario y límite por registro de membresía en entrega.','Unidad exacta de derecho, reinicio, reingreso, stock, retiro y compensación por falta de disponibilidad.'],['Café','Texto por visita, límite diario.','Día o visita; bebida, tamaño, extras, sedes y horarios.'],['Sellos y premio','Nueve sellos; personal registra ticket.','Compra elegible, tickets grupales, devoluciones, bebida gratuita, premio incluido y vencimientos.'],['15 %','Asistido por personal; no cálculo automático por membresía en compra digital.','Productos, acumulación, canales, redondeo e identificación en recibo.'],['Prioridad VIP','Promesa sin regla visible de prioridad.','Ventana o cupos reservados, solicitud, respuesta y alternativa.'],['Experiencias','Promesa de 48 h, cesión manual y no devolución del comprador.','Ventanas de venta, transferencias, cancelación por la casa, reembolso/reprogramación y límite por comprador.'],['Renovación y vencimiento','Automática consentida; si falta saldo vence sin deuda.','Avisos, recibos, recuperación, pérdida de plaza y si existe o no gracia.'],['Bono por alta','Nueva fila de membresía suma 500 puntos; renovar la misma no.','Una vez por persona o por cada reingreso pagado, y cómo se explica.'],['Espera y contacto','Se promete llamar/escribir por orden.','Registro, consentimiento, responsable, estado, retiro de la lista y plazo de respuesta.']])}<p>Estas decisiones requieren conocimiento comercial real. La auditoría propone cómo hacerlas verificables, pero no fija un nuevo precio ni reduce beneficios ya contratados.</p>`)
body+=section('estados','Contrato de estados recomendado',`<p>La API debería devolver el derecho y su razón: estado, período, inicio/fin, próxima disponibilidad, hora del servidor y referencia de comprobante. La interfaz puede representarlo sin reconstruir reglas distintas con booleanos históricos.</p>${rows(['Objeto','Estados mínimos','Transición observable'],[
['Membresía','Sin plan, activa con/sin renovación, renovación en curso, vencida por causa.','Fecha efectiva, cargo/recibo, causa y siguiente acción.'],['Beneficio','No elegible, disponible, código vigente, expirado, entregado, próxima ventana.','Solicitar código no consume; entrega autorizada consume una vez.'],['Premio por sellos','Acumulando, premio disponible, código vigente/expirado, entregado.','El premio sobrevive a la caducidad del código.'],['Experiencia','Próxima apertura, venta exclusiva, general, agotada, comprada, cedida, asistida, cancelada.','Comprador financiero separado de titular y asistente.'],['Transacción','Revisión, enviando, confirmada, rechazada, resultado incierto.','Cierre visual no significa cancelación del envío; el reintento conserva referencia.'],['Datos','Actuales, actualizando, última consulta con error, sin datos.','Refresco dirigido y mensaje de recuperación sin habilitar derechos ficticios.']])}`)
body+=section('ruta','Ruta de mejora y verificación',`${rows(['Orden','Entrega concreta','Responsable principal','Cierre verificable'],[
['1 · Acordar el contrato','Ficha versionada de cuota, períodos, topes y beneficios; resolver MC01–04 y MC12.','Dirección / operación / producto','No hay una promesa contradictoria en oferta, caja y API.'],['2 · Resolver integridad y lifecycle','Evaluación única de derechos; renovación explícita; códigos con vencimiento real; historial de decisiones.','Backend','Pruebas de bordes, referencias repetidas y registro de cada transición.'],['3 · Hacer usable el canje','Acciones arriba, oferta completa, salida de recarga, foco, pase adaptable, procesamiento y recibos.','Diseño / frontend','Canje y contratación comprensibles con teclado y móvil; MC09–15 y MC19 cubiertos.'],['4 · Cerrar la operación','Descuentos, espera, transferencias, correcciones de entrega y excepciones.','Caja / atención / backend','Ensayo de dos turnos con resultados y responsabilidades consistentes.'],['5 · Medir y optimizar','Eventos mínimos, costos, cohortes, pruebas de comprensión y rendimiento de campo.','Producto / finanzas / ingeniería','Línea base antes de prometer crecimiento o ampliar beneficios.']])}<p>Es un orden de dependencias, no una estimación cerrada de semanas. Cambiar el período de beneficios puede requerir migración de derechos; su costo se estima después de aprobar la regla. Las mejoras de foco, nombres, reflujo y acceso a recarga se pueden preparar en paralelo a esa decisión.</p><h3>Criterios de salida antes de publicar una implementación</h3><ul><li>Cliente, caja y servidor coinciden para activo, usado, vencido, reingreso, cambio de mes y falta de saldo.</li><li>Un ticket normalizado acredita una vez; una referencia de compra cobra una vez; mostrar código nunca consume.</li><li>El titular encuentra su comprobante y se conserva la historia de cancelación, renovación y transferencia.</li><li>Se prueba final de mes, fin de período, código casi vencido, petición lenta, desconexión y recuperación.</li><li>320 CSS px, texto ampliado, espaciado y nombre largo conservan contenido; foco permanece contextual. Validar NVDA/VoiceOver y dispositivo real.</li><li>Ensayo de concurrencia en PostgreSQL aislado para última butaca, plazas, gasto y cancelación coincidente con renovación.</li><li>Condiciones comerciales aprobadas y una ronda moderada con clientes nuevos, miembros y caja.</li></ul>`)
body+=section('economia','Economía y medición que permiten decidir',`<p><strong>La auditoría no demuestra rentabilidad ni un precio óptimo.</strong> Cien plazas a C$950 equivalen a C$95.000 nominales por ciclo si todas pagan esa cuota. No es utilidad, efectivo nuevo ni ingreso mensual garantizado: hay cuotas individuales, períodos de treinta días y saldo bonificado.</p><div class="formula">Contribución del ciclo = cuota económica neta + margen de compras adicionales después de descuentos − costos variables de beneficios − costo incremental de atención y capacidad.</div><p>Para medir efecto incremental se debe descontar además lo que esos clientes habrían comprado sin el programa. Registrar costo de bolsa y empaque, costo por café, uso de descuentos, extras, ocupación, atención, bonos y pérdida por sustitución de compras habituales. Segmentar por antigüedad y nivel de uso evita que el promedio oculte miembros muy costosos.</p>${rows(['Pregunta','Métrica sugerida','Cuidado de interpretación'],[
['¿Se entiende y se activa?','Oferta vista → confirmación abierta → alta pagada; primer sello y primer canje.','Visitas a la pestaña no equivalen a valor obtenido.'],['¿Dónde se detiene?','Saldo insuficiente → instrucciones de recarga → regreso → compra.','La recarga ocurre en caja: unir por referencia segura, no por suposición.'],['¿Se entrega lo prometido?','Código solicitado → entregado; expiraciones, rechazos por causa, tiempo de canje.','Emitir código no cuenta como entrega.'],['¿Se conserva al cliente?','Renovaciones sobre las elegibles; baja voluntaria frente a saldo insuficiente.','Las cohortes recientes todavía no han tenido oportunidad de renovar.'],['¿Se gana dinero adicional?','Contribución por ciclo/cohorte y compras comparables sin membresía.','Débito, saldo pagado, bono y efectivo son magnitudes distintas.'],['¿La operación es sostenible?','Descuentos correctamente aplicados, incidencias, tiempo de atención y stock.','Un bajo uso puede significar desinterés o dificultad de canje.'],['¿Es rápida y fiable?','Tiempo a acción útil, errores por endpoint, p75 LCP/INP/CLS por dispositivo.','El rendimiento de laboratorio no sustituye a visitantes reales.']])}<p>Eventos propuestos: vista de Club, oferta revisada, contratación confirmada, beneficio solicitado/entregado/rechazado, código expirado, renovación completada/fallida, cancelación, recarga orientada y entrada consultada. Definirlos con identificador pseudónimo, referencia y estado; excluir teléfono, código canjeable, token, alergias y otros datos innecesarios.</p><p>En pruebas moderadas, pedir: «Encontrá y usá tu café», «Explicá qué incluye Mesa Fundadora», «Qué harías si falta saldo» y «Cancelá la próxima renovación sin perder lo pagado». Medir comprensión, errores y tiempo. Las metas comerciales se fijan tras la línea base; no se proyecta un porcentaje de mejora sin evidencia.</p>`)
body+=section('referentes','Qué aprender de los referentes',`${rows(['Referencia','Práctica útil','Adaptación a La Bella Lupita'],[
['<a href="https://www.costa.co.uk/costa-club/terms-of-use">Costa Club</a>','Reglas concretas de qué compra acredita y qué canje incluye.','Conservar nueve sellos, pero definir su elegibilidad y premio.'],['<a href="https://www.pret.co.uk/en-GB/legal">Club Pret</a>','Límites operativos y próxima renovación explícitos.','Resolver ciclo y frecuencia sin importar precios o cláusulas británicas.'],['<a href="https://www.panerabread.com/en-us/mypanera/subscription/terms-and-conditions.html">Panera Sip Club</a>','Cuenta gratuita separada del plan y límites visibles.','Mostrar gratis/pago y oferta completa. La página actual indica 30 canjes por período; no copiar la antigua idea de ilimitado.']])}<p>El patrón útil es una promesa precisa que el cliente y el personal puedan aplicar igual. Ninguno de estos programas prueba qué precio, recompensa o frecuencia conviene a la clientela de Matagalpa/Jinotega. Esa decisión requiere costos y observación locales.</p>`)
body+=section('confianza','Transparencia y privacidad',`<p>La información oficial del <a href="https://www.mific.gob.ni/Inicio/Servicios/Servicio-Diprodec/Datos-Generales-y-Estad%C3%ADsticas/Seguimiento-y-Regulaci%C3%B3n-de-Precio">MIFIC</a> describe verificaciones de precios en moneda nacional, impuestos incluidos, correspondencia entre precio exhibido y cobrado, y condiciones promocionales. Esto refuerza la conveniencia de cerrar una ficha comercial consistente y comprobable. No se detectó aquí un cobro mayor al confirmado ni se emite una conclusión legal general.</p><p>Antes de introducir avisos automáticos o una lista de espera, definir finalidad, consentimiento, canal, baja y retención. Separar atención transaccional de marketing. El historial de derechos y reclamos debe poder explicarse al titular, con acceso del personal por función y registros sin secretos. La evaluación jurídica de las condiciones, privacidad, devoluciones y conservación debe usar las políticas reales y normativa aplicable, no supuestos de esta auditoría.</p>`)
body+=section('fuentes','Fuentes y paquete reproducible',`<p>Consultadas el 8 de octubre de 2026. Las fuentes externas sustentan criterios o referentes; los defectos de La Bella Lupita se sustentan en el código y ensayos adjuntos.</p>${rows(['Fuente primaria','Uso en el diagnóstico'],sources.map(([name,url,use])=>[`<a href="${url}">${e(name)}</a>`,e(use)]))}<h3>Evidencia local</h3><ul><li><a href="backlog-mi-club.json">Backlog completo en JSON</a> · prioridades, responsables, evidencia y aceptación.</li><li><a href="evidencia-ui/resultados-edge.json">Resultados Edge</a> y <a href="evidencia-ui/resultados-firefox.json">Firefox</a> · geometría, axe, estados y capturas.</li><li><a href="evidencia_tecnica.json">14 pruebas técnicas</a> y <a href="audit_tecnica.mjs">script backend</a>.</li><li><a href="auditar-ui.mjs">Script UI</a> · recompilar el frontend en build antes de repetir si cambia la app.</li><li><a href="evidencia-publica.json">Lectura pública y hashes</a> · observación puntual; sin credenciales.</li><li><a href="findings_tecnica.md">Análisis técnico</a>, <a href="findings_comercial.md">comercial</a> y <a href="findings_accesibilidad.md">accesibilidad</a> · informes de apoyo con líneas y matices. Las pruebas adicionales de ampliación se integraron en MC10 de este informe.</li><li><a href="verificacion.json">Resumen de verificación y alcance</a>.</li></ul><p>Reproducción desde esta carpeta: <code>node audit_tecnica.mjs</code> y <code>node auditar-ui.mjs</code>; en PowerShell, <code>$env:MOTOR='firefox'</code> selecciona Firefox. Usan las dependencias locales del proyecto, datos sintéticos y compilaciones auxiliares por proceso. La suite UI restringe tráfico al host local.</p><p class="small">Frontend publicado verificado: SHA256 JS ${pub.assets[0].sha256}; CSS ${pub.assets[1].sha256}. Las conclusiones de backend se limitan al código actual ensayado localmente.</p>`)
const html=`<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Auditoría integral de Mi Club · La Bella Lupita</title><style>
:root{--ink:#38241e;--muted:#6d574e;--paper:#fffaf3;--line:#dcc9b9;--brand:#53291e;--rose:#f8b0a5}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:85px}body{margin:0;background:#eee5dc;color:var(--ink);font:17px/1.65 system-ui,-apple-system,Segoe UI,sans-serif}main{max-width:1200px;margin:auto;background:var(--paper);box-shadow:0 0 80px #38241e0a}header{background:var(--brand);color:var(--paper);padding:70px 64px 48px}h1,h2,h3{line-height:1.15;letter-spacing:-.02em}h1{font:normal clamp(44px,6vw,78px)/1.05 Georgia,serif;margin:20px 0 30px}h1 em{color:var(--rose);font-weight:normal}h2{font:normal 36px/1.2 Georgia,serif;margin:0 0 26px}h3{font-size:23px;margin:14px 0}p{margin:0 0 20px}a{color:#8b3328;text-underline-offset:3px}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #b60032;outline-offset:4px}.eyebrow{font-size:13px;letter-spacing:.15em;font-weight:700}.lead{font-size:23px;line-height:1.55;max-width:900px}.small{font-size:13px;line-height:1.6;overflow-wrap:anywhere}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;border-top:1px solid #ffffff44;padding-top:28px;margin:30px 0}.stats b{display:block;font-size:42px;font-weight:500}.stats span{font-size:14px;display:block}.report-nav{position:sticky;top:0;z-index:3;display:flex;flex-wrap:wrap;gap:12px 20px;padding:14px 32px;background:#fffaf3f5;border-bottom:1px solid var(--line);backdrop-filter:blur(5px)}.report-nav a{font-size:14px;text-decoration:none;font-weight:600}button,input,select{font:inherit}button{border:1px solid var(--line);background:white;color:var(--ink);padding:7px 14px;cursor:pointer;border-radius:5px}.report-nav button{font-size:13px;margin-left:auto}section{padding:50px 64px;border-bottom:1px solid var(--line)}section p,section li{max-width:950px}li{margin-bottom:10px}.callout{border-left:5px solid #ac493c;background:#f7e8df;padding:22px 26px;margin-bottom:28px}.callout p{margin:0}.table-wrap{overflow:auto;margin:24px 0 30px}table{border-collapse:collapse;width:100%;font-size:14px;line-height:1.55;min-width:570px}th{text-align:left;background:#efe0d4;padding:13px;vertical-align:top}td{padding:14px 13px;border-bottom:1px solid var(--line);vertical-align:top}th:first-child,td:first-child{width:23%;font-weight:650}td:not(:first-child){min-width:190px}.gallery{display:grid;grid-template-columns:2fr 1fr 1fr;gap:20px}figure{margin:0}figure img{width:100%;height:350px;object-fit:cover;object-position:top;border:1px solid var(--line);background:#fff}figcaption{font-size:13px;line-height:1.5;padding-top:10px;color:var(--muted)}.filters{display:flex;flex-wrap:wrap;gap:15px;align-items:end;padding:20px;background:#eee0d4;border-radius:8px}.filters label{display:grid;gap:5px;font-size:13px;font-weight:600}.filters input,.filters select{padding:8px;border:1px solid #9f7c67;border-radius:4px;background:white;min-height:44px}.filters button{min-height:44px}.finding{border:1px solid var(--line);border-radius:8px;padding:27px;margin:20px 0;background:#fffdf9}.finding-top{display:flex;align-items:center;gap:12px;font-size:13px;font-weight:650}.pill{display:inline-block;padding:3px 10px;border-radius:20px;background:#ece5dc}.P1{color:#7e1e20;background:#fae0da}.P2{color:#775019;background:#f6ebcc}.P3{color:#31544b;background:#e5eeea}.status{font-size:13px;color:var(--muted);font-weight:600}details{border-top:1px solid var(--line);padding-top:15px;margin-top:16px}details p:first-of-type{margin-top:15px}summary{cursor:pointer;font-size:15px;font-weight:650;padding:8px 0}.evidence{font-size:13px;background:#f4ece4;padding:16px;overflow-wrap:anywhere}.proposal{border:1px solid var(--brand);max-width:700px;margin:32px auto;border-radius:8px;overflow:hidden}.proposal-head{display:flex;justify-content:space-between;gap:18px;padding:22px;background:var(--brand);color:white}.proposal-head span{font-size:12px}.proposal-row{padding:22px 26px;border-bottom:1px solid var(--line)}.proposal-row p{margin:6px 0}.proposal-row small{display:block;color:var(--muted);font-size:13px}.formula{font:normal 23px/1.55 Georgia,serif;border:1px solid var(--line);padding:25px;margin:25px 0;background:#f4e8dd}code{background:#ece3da;padding:3px 5px;font-size:13px;overflow-wrap:anywhere}#resultCount{font-size:13px;margin-top:14px}[hidden]{display:none!important}footer{padding:30px 64px;font-size:13px;color:var(--muted)}@media(max-width:760px){body{font-size:16px}header{padding:40px 22px}section{padding:38px 22px}.lead{font-size:20px}.stats{grid-template-columns:1fr 1fr}.report-nav{position:static;padding:18px 22px}.gallery{grid-template-columns:1fr}.gallery img{height:420px;object-fit:contain;object-position:top}.finding{padding:20px}.filters{align-items:stretch}.filters label{width:100%}h2{font-size:30px}footer{padding:22px}}@media print{body{background:white;font-size:11pt}main{box-shadow:none;max-width:none}header{padding:30px;background:white;color:#38241e}h1 em{color:#53291e}.stats{border-color:#ccc}.report-nav,.filters,#resultCount{display:none}section{padding:24px 0}h2{font-size:24pt}.finding{break-inside:avoid;padding:15px}.table-wrap{overflow:visible}table{min-width:0;font-size:9pt}td:not(:first-child){min-width:0}a{color:inherit}.gallery img{height:250px}details{display:block}details>*{display:block}.proposal{break-inside:avoid}}
</style></head><body><main>${body}<footer>La Bella Lupita · Mi Club · Diagnóstico del 8 de octubre de 2026. Evidencia, decisiones y mejoras propuestas. La aplicación no fue modificada.</footer></main><script>
const filter=()=>{const p=document.getElementById('priority').value,q=document.getElementById('search').value.toLowerCase().trim();let n=0;document.querySelectorAll('.finding').forEach(el=>{el.hidden=!((p==='all'||el.dataset.priority===p)&&(!q||el.dataset.search.includes(q)));if(!el.hidden)n++});document.getElementById('resultCount').textContent=n+' hallazgos visibles'};document.getElementById('priority').addEventListener('change',filter);document.getElementById('search').addEventListener('input',filter);document.getElementById('expand').addEventListener('click',()=>{const open=[...document.querySelectorAll('.finding:not([hidden]) details')].some(d=>!d.open);document.querySelectorAll('.finding:not([hidden]) details').forEach(d=>d.open=open);document.getElementById('expand').textContent=open?'Cerrar los detalles':'Abrir todos los detalles'});window.addEventListener('beforeprint',()=>document.querySelectorAll('details').forEach(d=>d.open=true));
</script></body></html>`
